	/// DL-86: value of the grazing sub-grid model at node k of alpha
	/// row `ai`, for k in [0, SUB_SIZE].  k==0 is the cosTheta->0
	/// boundary (exactly 1 for the G2 model, a baked per-alpha
	/// constant for the separable one), k==SUB_SIZE is the first bin
	/// center c0 itself.  Every below-c0 consumer -- LookupEss,
	/// LookupEssG2 and MSLobeDetail::BuildSegmentsFromRow -- reads the
	/// model through these two accessors, so the lookup and the
	/// sampler's segments describe the SAME curve by construction.
	///
	/// Every node value is a baked directional albedo in [0,1] (and
	/// the k==0 G2 boundary is exactly 1), so a convex combination of
	/// them is automatically in [0,1]: LookupEss/LookupEssG2's
	/// defensive r_max/r_min around the blend below cannot fire, and
	/// BuildSegmentsFromRow's un-clamped segment form is therefore
	/// describing the identical function, not a laxer one.
	inline Scalar SubNodeEss( const int ai, const int k )
	{
		if( k <= 0 ) return E_ss_LIMIT_TABLE[ai];
		if( k >= SUB_SIZE ) return E_ss_TABLE[ai][0];
		return E_ss_SUB_TABLE[ai][k-1];
	}

	/// DL-86: height-correlated-G2 twin of SubNodeEss above.  The
	/// k==0 boundary is the PROVABLE exact value 1: under the
	/// height-correlated Smith model the per-sample VNDF weight is
	/// G2(wi,wo)/G1(wi) = (1+Lambda(wi)) / (1+Lambda(wi)+Lambda(wo)),
	/// and Lambda(wi) ~ alpha/(2*cosWi) -> infinity as cosWi -> 0, so
	/// that ratio -> 1 for ANY finite Lambda(wo) -- i.e. every
	/// VNDF-sampled wo, however distributed, contributes weight -> 1.
	inline Scalar SubNodeEssG2( const int ai, const int k )
	{
		if( k <= 0 ) return Scalar(1.0);
		if( k >= SUB_SIZE ) return E_ss_TABLE_G2[ai][0];
		return E_ss_SUB_TABLE_G2[ai][k-1];
	}

	/// DL-86: map a cosTheta strictly below c0 onto the grazing
	/// sub-grid -- sub-interval index k0 in [0, SUB_SIZE-1] and the
	/// fraction within it.  Shared by LookupEss/LookupEssG2 and the
	/// DL-77 aniso lookups so all of them bin identically.
	inline void SubNodeIndex( const Scalar cc, const Scalar c0, int& k0, Scalar& kf )
	{
		const Scalar t = cc / c0 * Scalar(SUB_SIZE);
		k0 = (int)t;
		if( k0 < 0 ) k0 = 0;
		if( k0 > SUB_SIZE - 1 ) k0 = SUB_SIZE - 1;
		kf = t - Scalar(k0);
	}

	/// DL-105: alpha value of the main table's row 0 / row 1 -- the
	/// two endpoints the low-alpha sub-grid below is anchored to.
	static const Scalar ALPHA_LOW_A0 = Scalar(0.01);
	static const Scalar ALPHA_LOW_A1 = Scalar(0.01) + Scalar(1.0 - 0.01) * Scalar(1.0) / Scalar(LUT_SIZE - 1);

	/// DL-105: alpha value of low-alpha virtual node `idx` (idx in
	/// [0, ALPHA_LOW_TOTAL]).  idx==0 is the exact alpha->0 boundary,
	/// idx==ALPHA_SUB_FINE+1 is A0 (row 0), idx==ALPHA_LOW_TOTAL is A1
	/// (row 1) -- see the ALPHA_SUB_FINE/ALPHA_MID_SIZE comment above.
	inline Scalar AlphaLowNode( const int idx )
	{
		if( idx <= 0 ) return Scalar(0.0);
		if( idx <= ALPHA_SUB_FINE ) return ALPHA_LOW_A0 * pow( Scalar(2.0), Scalar(idx - (ALPHA_SUB_FINE + 1)) );
		if( idx == ALPHA_SUB_FINE + 1 ) return ALPHA_LOW_A0;
		if( idx < ALPHA_LOW_TOTAL )
		{
			const Scalar t = Scalar(idx - (ALPHA_SUB_FINE + 1)) / Scalar(ALPHA_MID_SIZE);
			return ALPHA_LOW_A0 * pow( ALPHA_LOW_A1 / ALPHA_LOW_A0, t );
		}
		return ALPHA_LOW_A1;
	}

	/// DL-105: map a STORED virtual index (1..ALPHA_SUB_FINE, or
	/// ALPHA_SUB_FINE+2..ALPHA_LOW_TOTAL-1) to its flat storage slot.
	/// `constexpr` (not just `inline`) so the DL-206 static_assert below
	/// can call it directly -- the two must never drift apart again.
	inline constexpr int AlphaLowSlot( const int idx )
	{
		if( idx <= ALPHA_SUB_FINE ) return idx - 1;
		return ALPHA_SUB_FINE + ( idx - (ALPHA_SUB_FINE + 2) );
	}

	/// DL-206 (docs/DEBT_LEDGER.md): pins `ALPHA_LOW_STORED` to the
	/// highest slot `AlphaLowSlot` ever actually returns, plus one --
	/// the last STORED mid-node virtual index is ALPHA_LOW_TOTAL-1
	/// (ALPHA_LOW_TOTAL itself is A1/row 1, never passed to
	/// AlphaLowSlot at all).  Fails to compile, rather than silently
	/// re-introducing a dead stored slot, if a future change to either
	/// side drifts out of sync.
	static_assert( AlphaLowSlot( ALPHA_LOW_TOTAL - 1 ) == ALPHA_LOW_STORED - 1,
		"ALPHA_LOW_STORED must equal the highest slot AlphaLowSlot ever returns, plus one" );

	/// DL-105: bracket a query alpha in [0, ALPHA_LOW_A1) against the
	/// 13-position AlphaLowNode list.  A plain linear scan (small,
	/// fixed size) rather than a closed-form index -- the geometric
	/// spacing makes a closed form awkward across the alpha->0
	/// boundary, and this runs only for alpha<ALPHA_LOW_A1 (very
	/// smooth surfaces), not the majority-path alpha>=ALPHA_LOW_A1
	/// case below.
	inline void AlphaLowIndex( const Scalar alpha, int& idx0, int& idx1, Scalar& frac )
	{
		const Scalar a = r_max( Scalar(0.0), alpha );
		idx0 = 0;
		for( int j = 0; j < ALPHA_LOW_TOTAL; j++ )
		{
			if( a >= AlphaLowNode( j + 1 ) ) idx0 = j + 1; else break;
		}
		if( idx0 > ALPHA_LOW_TOTAL - 1 ) idx0 = ALPHA_LOW_TOTAL - 1;
		idx1 = idx0 + 1;
		const Scalar lo = AlphaLowNode(idx0), hi = AlphaLowNode(idx1);
		frac = (hi > lo) ? r_max( Scalar(0.0), r_min( Scalar(1.0), (a - lo) / (hi - lo) ) ) : Scalar(0.0);
	}

	/// DL-105: ordinary-row / grazing-subrow / limit accessors for a
	/// low-alpha virtual node, dispatching between the exact
	/// alpha->0 boundary (idx<=0), the reused main-table rows
	/// (idx==A0's or A1's index), and the new baked sub/mid tables.
	inline Scalar AlphaLowOrdinary( const int idx, const int k )
	{
		if( idx <= 0 ) return Scalar(1.0);
		if( idx == ALPHA_SUB_FINE + 1 ) return E_ss_TABLE[0][k];
		if( idx >= ALPHA_LOW_TOTAL ) return E_ss_TABLE[1][k];
		return E_ss_ALPHA_LOW_TABLE[ AlphaLowSlot(idx) ][k];
	}

	inline Scalar AlphaLowOrdinaryG2( const int idx, const int k )
	{
		if( idx <= 0 ) return Scalar(1.0);
		if( idx == ALPHA_SUB_FINE + 1 ) return E_ss_TABLE_G2[0][k];
		if( idx >= ALPHA_LOW_TOTAL ) return E_ss_TABLE_G2[1][k];
		return E_ss_ALPHA_LOW_TABLE_G2[ AlphaLowSlot(idx) ][k];
	}

	inline Scalar AlphaLowGrazing( const int idx, const int k )
	{
		if( idx <= 0 ) return Scalar(1.0);
		if( idx == ALPHA_SUB_FINE + 1 ) return E_ss_SUB_TABLE[0][k];
		if( idx >= ALPHA_LOW_TOTAL ) return E_ss_SUB_TABLE[1][k];
		return E_ss_ALPHA_LOW_SUB_TABLE[ AlphaLowSlot(idx) ][k];
	}

	inline Scalar AlphaLowGrazingG2( const int idx, const int k )
	{
		if( idx <= 0 ) return Scalar(1.0);
		if( idx == ALPHA_SUB_FINE + 1 ) return E_ss_SUB_TABLE_G2[0][k];
		if( idx >= ALPHA_LOW_TOTAL ) return E_ss_SUB_TABLE_G2[1][k];
		return E_ss_ALPHA_LOW_SUB_TABLE_G2[ AlphaLowSlot(idx) ][k];
	}

	/// SEPARABLE-model cosTheta->0 boundary at a low-alpha node.  No
	/// G2 twin exists: that model's boundary is exactly 1 (returned
	/// by AlphaLowOrdinaryG2/AlphaLowGrazingG2's own idx<=0 branch).
	inline Scalar AlphaLowLimit( const int idx )
	{
		if( idx <= 0 ) return Scalar(1.0);
		if( idx == ALPHA_SUB_FINE + 1 ) return E_ss_LIMIT_TABLE[0];
		if( idx >= ALPHA_LOW_TOTAL ) return E_ss_LIMIT_TABLE[1];
		return E_ss_ALPHA_LOW_LIMIT_TABLE[ AlphaLowSlot(idx) ];
	}

	inline Scalar AlphaLowEavg( const int idx )
	{
		if( idx <= 0 ) return Scalar(1.0);
		if( idx == ALPHA_SUB_FINE + 1 ) return E_avg_TABLE[0];
		if( idx >= ALPHA_LOW_TOTAL ) return E_avg_TABLE[1];
		return E_avg_ALPHA_LOW_TABLE[ AlphaLowSlot(idx) ];
	}

	inline Scalar AlphaLowEavgG2( const int idx )
	{
		if( idx <= 0 ) return Scalar(1.0);
		if( idx == ALPHA_SUB_FINE + 1 ) return E_avg_TABLE_G2[0];
		if( idx >= ALPHA_LOW_TOTAL ) return E_avg_TABLE_G2[1];
		return E_avg_ALPHA_LOW_TABLE_G2[ AlphaLowSlot(idx) ];
	}

	/// DL-105: build an alpha-blended (essRow, subRow, essLimit)
	/// triple for a query alpha < ALPHA_LOW_A1, the SEPARABLE model.
	/// Callers feed this straight into MSLobeDetail::BuildSegmentsFromRow
	/// (the SAME function the main alpha>=ALPHA_LOW_A1 path uses), so
	/// LookupEss/BuildSegments/MSLobeZ cannot drift apart here either.
	inline void BuildLowAlphaRow( const Scalar alpha, Scalar essRow[LUT_SIZE], Scalar subRow[SUB_SIZE-1], Scalar& essLimit )
	{
		int idx0, idx1; Scalar f;
		AlphaLowIndex( alpha, idx0, idx1, f );
		for( int k = 0; k < LUT_SIZE; k++ )
			essRow[k] = (1-f) * AlphaLowOrdinary(idx0,k) + f * AlphaLowOrdinary(idx1,k);
		for( int k = 0; k < SUB_SIZE - 1; k++ )
			subRow[k] = (1-f) * AlphaLowGrazing(idx0,k) + f * AlphaLowGrazing(idx1,k);
		essLimit = (1-f) * AlphaLowLimit(idx0) + f * AlphaLowLimit(idx1);
	}

	/// DL-105: height-correlated-G2 twin of BuildLowAlphaRow above.
	/// No essLimit output: this model's cosTheta->0 boundary is
	/// exactly 1 at every alpha (matching BuildSegmentsG2's own
	/// Scalar(1.0) literal passed to BuildSegmentsFromRow).
	inline void BuildLowAlphaRowG2( const Scalar alpha, Scalar essRow[LUT_SIZE], Scalar subRow[SUB_SIZE-1] )
	{
		int idx0, idx1; Scalar f;
		AlphaLowIndex( alpha, idx0, idx1, f );
		for( int k = 0; k < LUT_SIZE; k++ )
			essRow[k] = (1-f) * AlphaLowOrdinaryG2(idx0,k) + f * AlphaLowOrdinaryG2(idx1,k);
		for( int k = 0; k < SUB_SIZE - 1; k++ )
			subRow[k] = (1-f) * AlphaLowGrazingG2(idx0,k) + f * AlphaLowGrazingG2(idx1,k);
	}

	/// Look up E_ss(cosTheta, alpha) with bilinear interpolation.
	///
	/// DL-86: below the first bin center c0 = 0.5/LUT_SIZE this used
	/// to flat-clamp to the c0 row, which mis-reads the true, sharply
	/// varying Ess right at the grazing limit (measured: alpha=0.01,
	/// cosTheta=0.002, independent 20M-sample VNDF quadrature reads
	/// 0.9174 for the SEPARABLE model against the flat clamp's
	/// 0.8947, a 2.5% under-read that grows the compensation weight
	/// (1-Ess) by 27.5%).  It now interpolates the BAKED sub-grid
	/// (E_ss_SUB_TABLE + E_ss_LIMIT_TABLE, via SubNodeEss) -- an
	/// extrapolated bin0->bin1 secant was tried first and is WORSE
	/// than the flat clamp here, because row 0 RISES with cosTheta
	/// (0.8947 at c0 vs 0.9731 at the next bin) so the secant
	/// extrapolates DOWNWARD, away from the true limit.
	/// MUST stay in sync with MSLobeDetail::BuildSegmentsFromRow's
	/// left end-cap -- MSPdf calls this function directly while
	/// SampleMSCosTheta inverts that segment's shape; both now read
	/// the same nodes through SubNodeEss, so they cannot disagree.
	///
	/// DL-105: below ALPHA_LOW_A1 (row 1's alpha), source the row
	/// from the low-alpha sub-grid (BuildLowAlphaRow) instead of the
	/// main table -- this covers BOTH the alpha<0.01 clamp-to-row-0
	/// range and the coarse row0->row1 cell; see ALPHA_SUB_FINE/
	/// ALPHA_MID_SIZE above.
	inline Scalar LookupEss( const Scalar cosTheta, const Scalar alpha )
	{
		if( alpha < ALPHA_LOW_A1 )
		{
			Scalar essRow[LUT_SIZE]; Scalar subRow[SUB_SIZE-1]; Scalar essLimit;
			BuildLowAlphaRow( alpha, essRow, subRow, essLimit );
			const Scalar cc2 = r_max(0.0, r_min(1.0, cosTheta));
			const Scalar c02 = Scalar(0.5) / Scalar(LUT_SIZE);
			if( cc2 < c02 )
			{
				int k0; Scalar kf;
				SubNodeIndex( cc2, c02, k0, kf );
				const Scalar s0 = (k0 <= 0) ? essLimit : subRow[k0-1];
				const Scalar s1 = (k0+1 >= SUB_SIZE) ? essRow[0] : subRow[k0];
				return r_max( Scalar(0.0), r_min( Scalar(1.0), (1-kf) * s0 + kf * s1 ) );
			}
			const Scalar c2 = cc2 * LUT_SIZE - 0.5;
			const int ci02 = (int)c2;
			const int ci12 = r_min(ci02 + 1, LUT_SIZE - 1);
			const Scalar cf2 = c2 - ci02;
			return (1-cf2) * essRow[ci02] + cf2 * essRow[ci12];
		}

		// Map alpha from [0.01, 1.0] to [0, LUT_SIZE-1]
		Scalar a = r_max(0.0, r_min(1.0, (alpha - 0.01) / (1.0 - 0.01))) * (LUT_SIZE - 1);
		int ai0 = (int)a;
		int ai1 = r_min(ai0 + 1, LUT_SIZE - 1);
		Scalar af = a - ai0;

		const Scalar cc = r_max(0.0, r_min(1.0, cosTheta));
		const Scalar c0 = Scalar(0.5) / Scalar(LUT_SIZE);
		if( cc < c0 )
		{
			int k0; Scalar kf;
			SubNodeIndex( cc, c0, k0, kf );
			const Scalar s0 = (1-af) * SubNodeEss(ai0, k0)     + af * SubNodeEss(ai1, k0);
			const Scalar s1 = (1-af) * SubNodeEss(ai0, k0 + 1) + af * SubNodeEss(ai1, k0 + 1);
			return r_max( Scalar(0.0), r_min( Scalar(1.0), (1-kf) * s0 + kf * s1 ) );
		}

		// Map cosTheta from cell centers: idx = cosTheta * LUT_SIZE - 0.5
		Scalar c = cc * LUT_SIZE - 0.5;
		int ci0 = (int)c;
		int ci1 = r_min(ci0 + 1, LUT_SIZE - 1);
		Scalar cf = c - ci0;

		// Bilinear interpolation
		Scalar v00 = E_ss_TABLE[ai0][ci0];
		Scalar v01 = E_ss_TABLE[ai0][ci1];
		Scalar v10 = E_ss_TABLE[ai1][ci0];
		Scalar v11 = E_ss_TABLE[ai1][ci1];
		return (1-af) * ((1-cf)*v00 + cf*v01) + af * ((1-cf)*v10 + cf*v11);
	}

	/// Look up E_avg(alpha) with linear interpolation.
	///
	/// DL-105: below ALPHA_LOW_A1, blend the low-alpha Eavg sub-grid
	/// instead -- see LookupEss's own DL-105 comment.
	inline Scalar LookupEavg( const Scalar alpha )
	{
		if( alpha < ALPHA_LOW_A1 )
		{
			int idx0, idx1; Scalar f;
			AlphaLowIndex( alpha, idx0, idx1, f );
			return (1-f) * AlphaLowEavg(idx0) + f * AlphaLowEavg(idx1);
		}
		Scalar a = r_max(0.0, r_min(1.0, (alpha - 0.01) / (1.0 - 0.01))) * (LUT_SIZE - 1);
		int ai0 = (int)a;
		int ai1 = r_min(ai0 + 1, LUT_SIZE - 1);
		Scalar af = a - ai0;
		return (1-af) * E_avg_TABLE[ai0] + af * E_avg_TABLE[ai1];
	}

	/// DL-63: height-correlated-G2 twin of LookupEss above -- reads
	/// E_ss_TABLE_G2 instead of E_ss_TABLE.  Use for GGXBRDF/GGXSPF/
	/// CoatedBRDF (height-correlated G2 single-scatter); CookTorrance
	/// keeps using LookupEss (separable G).
	///
	/// DL-86: below the first bin center c0 = 0.5/LUT_SIZE this used
	/// to flat-clamp to the c0 row, under-reading the true Ess right
	/// at the grazing limit and over-stating the Kulla-Conty
	/// multiscatter compensation there by up to ~9.9% relative
	/// (measured against an independent 20M-sample VNDF quadrature:
	/// alpha=0.01, cosTheta=0.0001, truth 0.99789 vs the flat clamp's
	/// 0.89927) -- an isotropic furnace GAIN confined to incidence
	/// beyond ~89.1 degrees.  It now interpolates the BAKED grazing
	/// sub-grid (E_ss_SUB_TABLE_G2, via SubNodeEssG2), anchored at
	/// the provable exact boundary Ess_G2(cosTheta=0)=1 (proof in
	/// SubNodeEssG2's own comment).  A single straight line from that
	/// boundary to bin 0 was tried first and is NOT sufficient: at
	/// alpha=0.01 the true curve DIPS to 0.8920 near cosTheta=0.010
	/// and only climbs to 1 as cosTheta itself goes to 0, so a
	/// straight line from the boundary over-reads by up to
	/// 5.7% -- a larger error, of the opposite sign, than the flat
	/// clamp it replaced.  Residual after the baked sub-grid
	/// (independent 20M-sample-per-point quadrature, alpha-row blend
	/// included, cosTheta in [1e-4, c0]): <=0.26% at every tested
	/// alpha in [0.01,1.0] EXCEPT inside the FIRST alpha cell (row 0
	/// alpha=0.01 to row 1 alpha=0.0419, a 4.2x ratio), where the
	/// ALPHA axis alone still contributes up to 1.6% -- and up to
	/// 5.1% below alpha=0.01, which the table clamps to row 0
	/// outright.  Both are DL-105, not this end-cap: neither moves
	/// with SUB_SIZE.  MUST stay in sync with
	/// MSLobeDetail::BuildSegmentsFromRow's left end-cap -- see
	/// LookupEss's own comment on why; both read the same nodes
	/// through SubNodeEssG2.
	///
	/// DL-105: below ALPHA_LOW_A1, source the row from the low-alpha
	/// sub-grid (BuildLowAlphaRowG2) instead -- see LookupEss's own
	/// DL-105 comment.
	inline Scalar LookupEssG2( const Scalar cosTheta, const Scalar alpha )
	{
		if( alpha < ALPHA_LOW_A1 )
		{
			Scalar essRow[LUT_SIZE]; Scalar subRow[SUB_SIZE-1];
			BuildLowAlphaRowG2( alpha, essRow, subRow );
			const Scalar cc2 = r_max(0.0, r_min(1.0, cosTheta));
			const Scalar c02 = Scalar(0.5) / Scalar(LUT_SIZE);
			if( cc2 < c02 )
			{
				int k0; Scalar kf;
				SubNodeIndex( cc2, c02, k0, kf );
				const Scalar s0 = (k0 <= 0) ? Scalar(1.0) : subRow[k0-1];
				const Scalar s1 = (k0+1 >= SUB_SIZE) ? essRow[0] : subRow[k0];
				return r_max( Scalar(0.0), r_min( Scalar(1.0), (1-kf) * s0 + kf * s1 ) );
			}
			const Scalar c2 = cc2 * LUT_SIZE - 0.5;
			const int ci02 = (int)c2;
			const int ci12 = r_min(ci02 + 1, LUT_SIZE - 1);
			const Scalar cf2 = c2 - ci02;
			return (1-cf2) * essRow[ci02] + cf2 * essRow[ci12];
		}

		Scalar a = r_max(0.0, r_min(1.0, (alpha - 0.01) / (1.0 - 0.01))) * (LUT_SIZE - 1);
		int ai0 = (int)a;
		int ai1 = r_min(ai0 + 1, LUT_SIZE - 1);
		Scalar af = a - ai0;

		const Scalar cc = r_max(0.0, r_min(1.0, cosTheta));
		const Scalar c0 = Scalar(0.5) / Scalar(LUT_SIZE);
		if( cc < c0 )
		{
			int k0; Scalar kf;
			SubNodeIndex( cc, c0, k0, kf );
			const Scalar s0 = (1-af) * SubNodeEssG2(ai0, k0)     + af * SubNodeEssG2(ai1, k0);
			const Scalar s1 = (1-af) * SubNodeEssG2(ai0, k0 + 1) + af * SubNodeEssG2(ai1, k0 + 1);
			return r_max( Scalar(0.0), r_min( Scalar(1.0), (1-kf) * s0 + kf * s1 ) );
		}

		Scalar c = cc * LUT_SIZE - 0.5;
		int ci0 = (int)c;
		int ci1 = r_min(ci0 + 1, LUT_SIZE - 1);
		Scalar cf = c - ci0;

		Scalar v00 = E_ss_TABLE_G2[ai0][ci0];
		Scalar v01 = E_ss_TABLE_G2[ai0][ci1];
		Scalar v10 = E_ss_TABLE_G2[ai1][ci0];
		Scalar v11 = E_ss_TABLE_G2[ai1][ci1];
		return (1-af) * ((1-cf)*v00 + cf*v01) + af * ((1-cf)*v10 + cf*v11);
	}

	/// DL-63: height-correlated-G2 twin of LookupEavg above.
	///
	/// DL-105: below ALPHA_LOW_A1, blend the low-alpha Eavg sub-grid
	/// instead -- see LookupEss's own DL-105 comment.
	inline Scalar LookupEavgG2( const Scalar alpha )
	{
		if( alpha < ALPHA_LOW_A1 )
		{
			int idx0, idx1; Scalar f;
			AlphaLowIndex( alpha, idx0, idx1, f );
			return (1-f) * AlphaLowEavgG2(idx0) + f * AlphaLowEavgG2(idx1);
		}
		Scalar a = r_max(0.0, r_min(1.0, (alpha - 0.01) / (1.0 - 0.01))) * (LUT_SIZE - 1);
		int ai0 = (int)a;
		int ai1 = r_min(ai0 + 1, LUT_SIZE - 1);
		Scalar af = a - ai0;
		return (1-af) * E_avg_TABLE_G2[ai0] + af * E_avg_TABLE_G2[ai1];
	}

	//////////////////////////////////////////////////////////////////
	// H6: multiscatter-lobe outgoing-direction sampler + matching pdf.
	//
	// The MS lobe's true energy in outgoing direction wo is proportional
	// to (1-Ess(cosWo,alpha))*cosWo -- the definition of E_avg above is
	// exactly its cosine-weighted hemisphere average:
	//   2 * integral_0^1 (1-Ess(alpha,mu)) * mu dmu == 1 - E_avg(alpha)
	// Sampling wo from THIS shape (instead of plain cosine-hemisphere)
	// makes the MS-lobe's importance-sampling weight collapse to a
	// bounded per-shading-point constant instead of blowing up at
	// grazing incidence (docs/... H6 design note; the old
	// ws*(1-Eavg) selection weight + cosine-sampled wo assumed
	// (1-Ess)=(1-Eavg) everywhere, which fails badly near cosTheta->0
	// on smooth surfaces).
	//
	// LookupEss(cosTheta,alpha) is PIECEWISE-LINEAR in cosTheta between
	// adjacent LUT bin centers (DL-86: between the grazing sub-grid's
	// own nodes below the first bin center c0, and flat-clamped above
	// the last center) -- exactly what its bilinear-interpolation code
	// computes, and bilinear interpolation is separable, so blending the
	// two alpha rows first and then interpolating cosTheta (as done
	// below) is algebraically IDENTICAL to LookupEss's simultaneous
	// bilinear form for any (cosTheta, alpha).  That makes
	// shape(cos) = (1-LookupEss(cos,alpha))*cos a piecewise-QUADRATIC
	// function of cos with an EXACT closed-form integral and an exactly
	// invertible per-segment CDF (monotone; solved with a bracketed
	// Newton-bisection hybrid -- no numerical-quadrature approximation
	// anywhere).  MSPdf() below evaluates LookupEss directly, so the
	// density it reports for ANY cosWo is algebraically identical to the
	// shape MSLobeZ/SampleMSCosTheta integrate and sample: pdf and
	// sampler share the SAME LookupEss piecewise-linear model and cannot
	// drift apart.
	//////////////////////////////////////////////////////////////////

	namespace MSLobeDetail
	{
		// One [lo,hi] segment of the piecewise-linear-in-cosTheta Ess
		// model: a DL-86 grazing sub-interval (below the first bin
		// center), the linear span between two adjacent bin centers, or
		// the flat right end-cap above the last center.
		// Ess(cos) = essLo + slope*(cos-lo) for cos in [lo,hi].
		struct Segment
		{
			Scalar lo, hi;
			Scalar essLo, slope;
		};

		// Build the LUT_SIZE+SUB_SIZE segments (40 at SUB_SIZE=8:
		// SUB_SIZE grazing sub-intervals + LUT_SIZE-1 interior spans +
		// 1 right cap) from an already-resolved essRow / subRow / essLimit
		// (either a single exact LUT row, or LookupEss's alpha-blended one).
		//
		// DL-86: the left end-cap [0, c0] used to be a single FLAT
		// segment (Ess clamped to row 0).  It is now SUB_SIZE linear
		// pieces through the baked grazing sub-grid, reading exactly the
		// nodes SubNodeEss/SubNodeEssG2 give LookupEss/LookupEssG2 -- this
		// is load-bearing, not cosmetic: MSPdf/MSPdfG2 call
		// LookupEss/LookupEssG2 directly while SampleMSCosTheta/
		// SampleMSCosThetaG2 sample from THESE segments, and the file's
		// own header comment guarantees the two "cannot drift apart".
		// `essLimit` is the cosTheta=0 boundary value (1 for the
		// height-correlated G2 model, E_ss_LIMIT_TABLE's blended row for
		// the separable one); `subRow` holds the SUB_SIZE-1 interior
		// nodes.  All three inputs are LINEAR in the alpha blend, so this
		// preserves MSLobeZ/MSLobeZG2's documented "Z is an exact affine
		// function of af" per-row-then-blend optimization unchanged.
		inline void BuildSegmentsFromRow( const Scalar essRow[LUT_SIZE], const Scalar subRow[SUB_SIZE-1], const Scalar essLimit, Segment segs[LUT_SIZE + SUB_SIZE], int& nSegs )
		{
			nSegs = 0;
			const Scalar c0 = 0.5 / Scalar(LUT_SIZE);
			const Scalar cLast = (Scalar(LUT_SIZE) - 0.5) / Scalar(LUT_SIZE);

			// DL-86 grazing sub-intervals covering [0, c0].
			const Scalar h = c0 / Scalar(SUB_SIZE);
			for( int k = 0; k < SUB_SIZE; k++ )
			{
				const Scalar vLo = (k == 0) ? essLimit : subRow[k-1];
				const Scalar vHi = (k == SUB_SIZE - 1) ? essRow[0] : subRow[k];
				segs[nSegs].lo = Scalar(k) * h; segs[nSegs].hi = Scalar(k + 1) * h;
				segs[nSegs].essLo = vLo;
				segs[nSegs].slope = (vHi - vLo) / h;
				nSegs++;
			}

			// Interior linear spans between adjacent bin centers.
			for( int k = 0; k < LUT_SIZE - 1; k++ )
			{
				const Scalar ck  = (k + 0.5) / Scalar(LUT_SIZE);
				const Scalar ck1 = (k + 1.5) / Scalar(LUT_SIZE);
				segs[nSegs].lo = ck; segs[nSegs].hi = ck1;
				segs[nSegs].essLo = essRow[k];
				segs[nSegs].slope = (essRow[k+1] - essRow[k]) / (ck1 - ck);
				nSegs++;
			}

			// Right flat end-cap [cLast, 1]: Ess clamped to row LUT_SIZE-1.
			segs[nSegs].lo = cLast; segs[nSegs].hi = 1.0;
			segs[nSegs].essLo = essRow[LUT_SIZE-1]; segs[nSegs].slope = 0.0;
			nSegs++;
		}

		// Build the segments for a fixed alphaEff, using EXACTLY LookupEss's
		// alpha-row blend.
		//
		// DL-105: below ALPHA_LOW_A1, source the row from the low-alpha
		// sub-grid instead -- MUST stay in sync with LookupEss's own
		// low-alpha branch, which is why both call BuildLowAlphaRow.
		inline void BuildSegments( const Scalar alphaEff, Segment segs[LUT_SIZE + SUB_SIZE], int& nSegs )
		{
			if( alphaEff < ALPHA_LOW_A1 )
			{
				Scalar essRow[LUT_SIZE]; Scalar subRow[SUB_SIZE-1]; Scalar essLimit;
				BuildLowAlphaRow( alphaEff, essRow, subRow, essLimit );
				BuildSegmentsFromRow( essRow, subRow, essLimit, segs, nSegs );
				return;
			}

			Scalar a = r_max(0.0, r_min(1.0, (alphaEff - 0.01) / (1.0 - 0.01))) * (LUT_SIZE - 1);
			int ai0 = (int)a;
			int ai1 = r_min(ai0 + 1, LUT_SIZE - 1);
			Scalar af = a - ai0;

			Scalar essRow[LUT_SIZE];
			for( int k = 0; k < LUT_SIZE; k++ )
				essRow[k] = (1-af) * E_ss_TABLE[ai0][k] + af * E_ss_TABLE[ai1][k];

			// DL-86: the same blend on the grazing sub-grid and its
			// cosTheta=0 boundary constant.
			Scalar subRow[SUB_SIZE-1];
			for( int k = 0; k < SUB_SIZE - 1; k++ )
				subRow[k] = (1-af) * E_ss_SUB_TABLE[ai0][k] + af * E_ss_SUB_TABLE[ai1][k];
			const Scalar essLimit = (1-af) * E_ss_LIMIT_TABLE[ai0] + af * E_ss_LIMIT_TABLE[ai1];

			BuildSegmentsFromRow( essRow, subRow, essLimit, segs, nSegs );
		}

		// DL-63: height-correlated-G2 twin of BuildSegments above, using
		// EXACTLY LookupEssG2's alpha-row blend (E_ss_TABLE_G2 instead of
		// E_ss_TABLE).  Segment/SegShape/SegCDF/SegTotal/SegInvert and
		// BuildSegmentsFromRow are already table-agnostic (they only see
		// an already-resolved essRow), so only the alpha-row blend needs
		// a G2-specific twin.
		//
		// DL-105: below ALPHA_LOW_A1, source the row from the low-alpha
		// sub-grid instead -- MUST stay in sync with LookupEssG2's own
		// low-alpha branch, which is why both call BuildLowAlphaRowG2.
		inline void BuildSegmentsG2( const Scalar alphaEff, Segment segs[LUT_SIZE + SUB_SIZE], int& nSegs )
		{
			if( alphaEff < ALPHA_LOW_A1 )
			{
				Scalar essRow[LUT_SIZE]; Scalar subRow[SUB_SIZE-1];
				BuildLowAlphaRowG2( alphaEff, essRow, subRow );
				BuildSegmentsFromRow( essRow, subRow, Scalar(1.0), segs, nSegs );
				return;
			}

			Scalar a = r_max(0.0, r_min(1.0, (alphaEff - 0.01) / (1.0 - 0.01))) * (LUT_SIZE - 1);
			int ai0 = (int)a;
			int ai1 = r_min(ai0 + 1, LUT_SIZE - 1);
			Scalar af = a - ai0;

			Scalar essRow[LUT_SIZE];
			for( int k = 0; k < LUT_SIZE; k++ )
				essRow[k] = (1-af) * E_ss_TABLE_G2[ai0][k] + af * E_ss_TABLE_G2[ai1][k];

			// DL-86: this model's cosTheta=0 boundary is exactly 1, so
			// only the interior sub-nodes need blending.
			Scalar subRow[SUB_SIZE-1];
			for( int k = 0; k < SUB_SIZE - 1; k++ )
				subRow[k] = (1-af) * E_ss_SUB_TABLE_G2[ai0][k] + af * E_ss_SUB_TABLE_G2[ai1][k];

			BuildSegmentsFromRow( essRow, subRow, Scalar(1.0), segs, nSegs );
		}

		// shape(cos) = (1-Ess(cos))*cos within a segment; y = cos - lo.
		inline Scalar SegShape( const Segment& s, const Scalar y )
		{
			const Scalar ess = s.essLo + s.slope * y;
			return r_max( 0.0, (1.0 - ess) * (s.lo + y) );
		}

		// Exact antiderivative F(y) = integral_0^y SegShape(t) dt.
		// shape(y) = P + Q*y + R*y^2 with P=(1-essLo)*lo, Q=(1-essLo)-slope*lo,
		// R=-slope (obtained by expanding (1-essLo-slope*y)*(lo+y)).
		inline Scalar SegCDF( const Segment& s, const Scalar y )
		{
			const Scalar P = (1.0 - s.essLo) * s.lo;
			const Scalar Q = (1.0 - s.essLo) - s.slope * s.lo;
			const Scalar R = -s.slope;
			return P * y + Q * y * y * 0.5 + R * y * y * y * (1.0 / 3.0);
		}

		inline Scalar SegTotal( const Segment& s )
		{
			return SegCDF( s, s.hi - s.lo );
		}

		// Invert F(y) = target for y in [0,w] via Newton-bisection (F is
		// monotone non-decreasing since SegShape >= 0 everywhere shape is
		// physical).  30 iterations is comfortably converged for a cubic
		// on a bounded interval; the bisection fallback guarantees
		// convergence even if a Newton step would leave the bracket.
		inline Scalar SegInvert( const Segment& s, const Scalar target, const Scalar w )
		{
			Scalar ylo = 0.0, yhi = w;
			Scalar y = w * 0.5;
			for( int it = 0; it < 30; it++ )
			{
				const Scalar Fy = SegCDF( s, y );
				const Scalar diff = Fy - target;
				if( fabs(diff) < 1e-13 ) break;
				if( diff > 0 ) yhi = y; else ylo = y;

				const Scalar deriv = SegShape( s, y );
				Scalar yNext = (deriv > 1e-12) ? (y - diff / deriv) : (0.5 * (ylo + yhi));
				if( !(yNext > ylo && yNext < yhi) ) yNext = 0.5 * (ylo + yhi);
				y = yNext;
			}
			return y;
		}
	}

	/// Exact normalization for the MS-lobe outgoing-direction shape:
	///   I(alpha) = integral_0^1 (1-Ess(alpha,mu))*mu dmu   (segment-exact)
	///   Z(alpha) = 2 * I(alpha)  (== 1-E_avg(alpha) in the continuum
	///   limit; computed here from the SAME piecewise-linear Ess model
	///   that LookupEss / SampleMSCosTheta use, so it cannot drift out of
	///   sync with either).
	///
	/// H6 perf note: this used to call BuildSegments() (O(LUT_SIZE) to
	/// build the blended row + O(LUT_SIZE) segment integrals) on EVERY
	/// call, and it is evaluated per-NEE-light-sample from GGXSPF /
	/// CookTorranceSPF's Pdf/PdfNM.  Per LookupEss's own alpha blend,
	/// essRow(af) = (1-af)*E_ss_TABLE[ai0] + af*E_ss_TABLE[ai1] is LINEAR
	/// in af for a fixed (ai0,ai1) pair; SegCDF/SegTotal are themselves
	/// linear in (essLo, slope) (see their definitions above), and
	/// (essLo, slope) are each linear in essRow -- so I(alpha), and hence
	/// Z(alpha) = 2*I(alpha), is an EXACT affine (linear) function of af
	/// within one alpha bin.  That means Z(alphaEff) can be obtained by
	/// precomputing the exact per-row Z (Z evaluated with essRow pinned
	/// to a single LUT row, i.e. af=0) ONCE per row and then doing the
	/// SAME (1-af)/af blend LookupEss uses for Ess itself -- an O(1)
	/// lookup that is algebraically IDENTICAL to re-running
	/// BuildSegments+SegTotal every call, not an approximation.
	///
	/// DL-105: below ALPHA_LOW_A1 this does NOT use the cached-affine
	/// row shortcut above -- it recomputes segments+SegTotal directly
	/// from BuildLowAlphaRow every call, a deliberate perf/simplicity
	/// trade-off for a rare regime (very smooth surfaces, alpha<0.0419)
	/// rather than precomputing and affine-blending Z at the 13 low-
	/// alpha virtual nodes too.  Correctness does not depend on the
	/// cache: MSPdf calls LookupEss (also low-alpha-aware) and
	/// SampleMSCosTheta calls BuildSegments (also low-alpha-aware) --
	/// as long as this function's Z integrates the SAME row those two
	/// use, which it does (BuildLowAlphaRow is the single source both
	/// this function and BuildSegments read).
	inline Scalar MSLobeZ( const Scalar alphaEff )
	{
		if( alphaEff < ALPHA_LOW_A1 )
		{
			Scalar essRow[LUT_SIZE]; Scalar subRow[SUB_SIZE-1]; Scalar essLimit;
			BuildLowAlphaRow( alphaEff, essRow, subRow, essLimit );
			MSLobeDetail::Segment segs[LUT_SIZE + SUB_SIZE];
			int nSegs = 0;
			MSLobeDetail::BuildSegmentsFromRow( essRow, subRow, essLimit, segs, nSegs );
			Scalar I = 0.0;
			for( int i = 0; i < nSegs; i++ )
				I += MSLobeDetail::SegTotal( segs[i] );
			return 2.0 * I;
		}

		// Per-alpha-row Z, computed once (C++11 magic-statics: thread-safe
		// initialization, no locking on the steady-state read path).
		static const std::array<Scalar, LUT_SIZE> rowZ = []() {
			std::array<Scalar, LUT_SIZE> z{};
			for( int row = 0; row < LUT_SIZE; row++ )
			{
				MSLobeDetail::Segment segs[LUT_SIZE + SUB_SIZE];
				int nSegs = 0;
				MSLobeDetail::BuildSegmentsFromRow( E_ss_TABLE[row], E_ss_SUB_TABLE[row], E_ss_LIMIT_TABLE[row], segs, nSegs );
				Scalar I = 0.0;
				for( int i = 0; i < nSegs; i++ )
					I += MSLobeDetail::SegTotal( segs[i] );
				z[row] = 2.0 * I;
			}
			return z;
		}();

		// Same alpha -> (ai0, ai1, af) mapping as LookupEss/BuildSegments.
		const Scalar a = r_max(0.0, r_min(1.0, (alphaEff - 0.01) / (1.0 - 0.01))) * (LUT_SIZE - 1);
		const int ai0 = (int)a;
		const int ai1 = r_min(ai0 + 1, LUT_SIZE - 1);
		const Scalar af = a - ai0;
		return (1.0 - af) * rowZ[ai0] + af * rowZ[ai1];
	}

	/// Sample cosWo ~ (1-Ess(alpha,cosWo))*cosWo / I(alpha) via exact
	/// per-segment CDF inversion.  u1 in [0,1). Returns cosWo in [0,1].
	/// Azimuth is NOT handled here (uniform; caller draws it separately).
	inline Scalar SampleMSCosTheta( const Scalar alphaEff, const Scalar u1 )
	{
		MSLobeDetail::Segment segs[LUT_SIZE + SUB_SIZE];
		int nSegs = 0;
		MSLobeDetail::BuildSegments( alphaEff, segs, nSegs );

		Scalar totals[LUT_SIZE + SUB_SIZE];
		Scalar I = 0.0;
		for( int i = 0; i < nSegs; i++ )
		{
			totals[i] = MSLobeDetail::SegTotal( segs[i] );
			I += totals[i];
		}
		if( I <= 1e-15 ) return r_max( 0.0, r_min( 1.0, u1 ) );	// degenerate fallback

		const Scalar target = r_max( 0.0, r_min( I, u1 * I ) );
		int seg = 0;
		Scalar running = 0.0;
		while( seg < nSegs - 1 && running + totals[seg] < target )
		{
			running += totals[seg];
			seg++;
		}
		const Scalar localTarget = r_max( 0.0, r_min( totals[seg], target - running ) );
		const Scalar y = MSLobeDetail::SegInvert( segs[seg], localTarget, segs[seg].hi - segs[seg].lo );
		return r_max( 0.0, r_min( 1.0, segs[seg].lo + y ) );
	}

	/// Solid-angle density of SampleMSCosTheta's output, expressed the
	/// same way as this codebase's other cosine-hemisphere pdfs (a
	/// function of cosTheta alone; azimuth is uniform and already folded
	/// in).  Uses LookupEss directly -- the SAME piecewise-linear model
	/// the sampler above is built from -- so this can never drift out of
	/// sync with what was actually sampled (see file-header comment).
	/// `Z` must be MSLobeZ(alphaEff) (callers compute it once per shading
	/// point and reuse it across the diffuse/specular/MS mixPdf sites).
	inline Scalar MSPdf( const Scalar cosTheta, const Scalar alphaEff, const Scalar Z )
	{
		if( Z <= 1e-15 ) return 0.0;
		const Scalar c = r_max( 0.0, r_min( 1.0, cosTheta ) );
		return r_max( 0.0, (1.0 - LookupEss( c, alphaEff )) * c / (RISE::PI * Z) );
	}

	//////////////////////////////////////////////////////////////////
	// DL-63: height-correlated-G2 twins of MSLobeZ/SampleMSCosTheta/
	// MSPdf above -- same H6 outgoing-direction shape/sampler/pdf
	// machinery, sourced from E_ss_TABLE_G2/LookupEssG2 instead of
	// E_ss_TABLE/LookupEss.  GGXSPF's multiscatter lobe (which renders
	// with height-correlated G2) uses these so its sampled direction,
	// reported density, and the F_ms/f_ms energy terms (LookupEavgG2/
	// LookupEssG2) all stay calibrated to the SAME masking-shadowing
	// model; CookTorranceSPF keeps using the separable-model MSLobeZ/
	// SampleMSCosTheta/MSPdf above, unchanged.
	//////////////////////////////////////////////////////////////////

	/// DL-63: height-correlated-G2 twin of MSLobeZ above.
	///
	/// DL-105: below ALPHA_LOW_A1, recompute directly from
	/// BuildLowAlphaRowG2 instead of the cached-affine row shortcut --
	/// see MSLobeZ's own comment for the rationale.
	inline Scalar MSLobeZG2( const Scalar alphaEff )
	{
		if( alphaEff < ALPHA_LOW_A1 )
		{
			Scalar essRow[LUT_SIZE]; Scalar subRow[SUB_SIZE-1];
			BuildLowAlphaRowG2( alphaEff, essRow, subRow );
			MSLobeDetail::Segment segs[LUT_SIZE + SUB_SIZE];
			int nSegs = 0;
			MSLobeDetail::BuildSegmentsFromRow( essRow, subRow, Scalar(1.0), segs, nSegs );
			Scalar I = 0.0;
			for( int i = 0; i < nSegs; i++ )
				I += MSLobeDetail::SegTotal( segs[i] );
			return 2.0 * I;
		}

		static const std::array<Scalar, LUT_SIZE> rowZ = []() {
			std::array<Scalar, LUT_SIZE> z{};
			for( int row = 0; row < LUT_SIZE; row++ )
			{
				MSLobeDetail::Segment segs[LUT_SIZE + SUB_SIZE];
				int nSegs = 0;
				MSLobeDetail::BuildSegmentsFromRow( E_ss_TABLE_G2[row], E_ss_SUB_TABLE_G2[row], Scalar(1.0), segs, nSegs );
				Scalar I = 0.0;
				for( int i = 0; i < nSegs; i++ )
					I += MSLobeDetail::SegTotal( segs[i] );
				z[row] = 2.0 * I;
			}
			return z;
		}();

		const Scalar a = r_max(0.0, r_min(1.0, (alphaEff - 0.01) / (1.0 - 0.01))) * (LUT_SIZE - 1);
		const int ai0 = (int)a;
		const int ai1 = r_min(ai0 + 1, LUT_SIZE - 1);
		const Scalar af = a - ai0;
		return (1.0 - af) * rowZ[ai0] + af * rowZ[ai1];
	}

	/// DL-63: height-correlated-G2 twin of SampleMSCosTheta above.
	inline Scalar SampleMSCosThetaG2( const Scalar alphaEff, const Scalar u1 )
	{
		MSLobeDetail::Segment segs[LUT_SIZE + SUB_SIZE];
		int nSegs = 0;
		MSLobeDetail::BuildSegmentsG2( alphaEff, segs, nSegs );

		Scalar totals[LUT_SIZE + SUB_SIZE];
		Scalar I = 0.0;
		for( int i = 0; i < nSegs; i++ )
		{
			totals[i] = MSLobeDetail::SegTotal( segs[i] );
			I += totals[i];
		}
		if( I <= 1e-15 ) return r_max( 0.0, r_min( 1.0, u1 ) );	// degenerate fallback

		const Scalar target = r_max( 0.0, r_min( I, u1 * I ) );
		int seg = 0;
		Scalar running = 0.0;
		while( seg < nSegs - 1 && running + totals[seg] < target )
		{
			running += totals[seg];
			seg++;
		}
		const Scalar localTarget = r_max( 0.0, r_min( totals[seg], target - running ) );
		const Scalar y = MSLobeDetail::SegInvert( segs[seg], localTarget, segs[seg].hi - segs[seg].lo );
		return r_max( 0.0, r_min( 1.0, segs[seg].lo + y ) );
	}

	/// DL-63: height-correlated-G2 twin of MSPdf above.
	inline Scalar MSPdfG2( const Scalar cosTheta, const Scalar alphaEff, const Scalar Z )
	{
		if( Z <= 1e-15 ) return 0.0;
		const Scalar c = r_max( 0.0, r_min( 1.0, cosTheta ) );
		return r_max( 0.0, (1.0 - LookupEssG2( c, alphaEff )) * c / (RISE::PI * Z) );
	}

	static const int ANISO_ALPHA_SIZE = 24;
	static const int ANISO_COS_SIZE = 32;
	static const int ANISO_PHI_SIZE = 13;

	/// DL-77: per-azimuth (NOT azimuthally-averaged) height-
	/// correlated-G2 single-scatter directional albedo -- the
	/// primary bake; E_ss_TABLE_G2_ANISO below is DERIVED from this
	/// by trapezoidal-averaging over phi.  Indexed as
	/// E_ss_TABLE_G2_ANISO_PHI[alphaXIdx][alphaYIdx][phiIdx][cosThetaIdx],
	/// alphaX,alphaY each mapped linearly from 0.01 to 1.0 (P2-2,
	/// debt-ggx3: this used to be resolved by (ratio,alphaEff)
	/// instead, which left most nominal grid cells physically
